sys_script_include.script:
var AggregationManagementUtils = Class.create();
AggregationManagementUtils.prototype = {
    initialize: function() {
    },

    newConnectionRequestAggregations: function(request) {
		var requestsysId = request.getValue('sys_id');
		var areaSysId = request.getValue('area');
		var request_type= request.getValue('request_type');
		var request_subtype =request.getValue('request_subtype');
		var description=request.getValue('description');
		var short_description=request.getValue('short_description');
		var aggregationSysId ='';
		//var requested_by=request.getValue('requested_by');

		var aggregation =new GlideRecord(
			'x_1966159_utilit_0_aggregations'
        );
		aggregation.addQuery('aggregation_type', 'new_connection');
        aggregation.addQuery('area', areaSysId);
        aggregation.addQuery('active', true);

        aggregation.query();
		if (aggregation.next()){
			aggregationSysId = aggregation.getValue('sys_id');
		}     
        else {
			aggregation.initialize();
			//aggregation.setValue('aggregation_type',request_type);
			aggregation.setValue('aggregation_type',request_type);
			aggregation.setValue('aggregation_request_subtype',request_subtype);
			aggregation.setValue('area',areaSysId);
			aggregationSysId = aggregation.insert();


        }
		//aggrgation member record creation 
		var aggregationMember =new GlideRecord('x_1966159_utilit_0_aggregation_members');
		aggregationMember.initialize();
		aggregationMember.setValue('aggregation', aggregationSysId);
		aggregationMember.setValue('new_connection_request',requestsysId);
		aggregationMember.insert();
	var updateAggregation = new GlideRecord(
		'x_1966159_utilit_0_aggregations'
		);
	updateAggregation.get(aggregationSysId);
	var totalRequests = parseInt(updateAggregation.getValue('total_requests'), 10);
	totalRequests = totalRequests + 1;
	updateAggregation.setValue('total_requests', totalRequests);
	updateAggregation.update();

    },

	meterFaultRequestAggregations: function(request) {

    var requestsysId = request.getValue('sys_id');
    var request_type = request.getValue('request_type');
    var request_subtype = request.getValue('request_subtype');
    var description = request.getValue('description');
    var short_description = request.getValue('short_description');
    var aggregationSysId = '';
    var service_connection_sysid = request.getValue('service_connection');
    var transformer_sysid = '';

    var sc = new GlideRecord('x_1966159_utilit_0_svc_conn');
    sc.addQuery('sys_id', service_connection_sysid);
    sc.query();

    if (sc.next()) {
        transformer_sysid = sc.getValue('transformer');
    }

    var aggregation = new GlideRecord(
        'x_1966159_utilit_0_aggregations'
    );

    aggregation.addQuery('aggregation_type', 'meter_fault');
    aggregation.addQuery('transformer', transformer_sysid);
    aggregation.addQuery('active', true);

    aggregation.query();

    if (aggregation.next()) {
        aggregationSysId = aggregation.getValue('sys_id');

    } else {

        var aggregation = new GlideRecord(
            'x_1966159_utilit_0_aggregations'
        );

        aggregation.initialize();
        aggregation.setValue('aggregation_type', request_type);
        aggregation.setValue('aggregation_request_subtype', request_subtype);
        aggregation.setValue('transformer', transformer_sysid);

        aggregationSysId = aggregation.insert();
    }

    // Aggregation Member record creation
    var aggregationMember = new GlideRecord(
        'x_1966159_utilit_0_aggregation_members'
    );

    aggregationMember.initialize();
    aggregationMember.setValue('aggregation', aggregationSysId);
    aggregationMember.setValue('meter_fault_request', requestsysId);

    var aggregationMembersysid = aggregationMember.insert();

    // Update Aggregation Total Requests
    if (aggregationMembersysid) {

        var updateAggregation = new GlideRecord(
            'x_1966159_utilit_0_aggregations'
        );

        updateAggregation.get(aggregationSysId);

        var totalRequests = parseInt(
            updateAggregation.getValue('total_requests'), 10
        );

        totalRequests = totalRequests + 1;

        updateAggregation.setValue('total_requests', totalRequests);
        updateAggregation.update();
    }

	},

powerOutageRequestAggregations: function(request) {

    var requestsysId = request.getValue('sys_id');
    var request_type = request.getValue('request_type');
    var request_subtype = request.getValue('request_subtype');
    var description = request.getValue('description');
    var short_description = request.getValue('short_description');
    var aggregationSysId = '';
    var service_connection_sysid = request.getValue('service_connection');
    var transformer_sysid = '';

    var sc = new GlideRecord('x_1966159_utilit_0_svc_conn');
    sc.addQuery('sys_id', service_connection_sysid);
    sc.query();

    if (sc.next()) {

        transformer_sysid = sc.getValue('transformer');

        var t = new GlideRecord('x_1966159_utilit_0_transformer');
        t.addQuery('sys_id', transformer_sysid);
        t.query();

        var feeder_sysid = '';

        if (t.next()) {
            feeder_sysid = t.getValue('feeder');
        }

        var f = new GlideRecord('x_1966159_utilit_0_feeder');
        f.addQuery('sys_id', feeder_sysid);
        f.query();

        var substation_sysid = '';

        if (f.next()) {
            substation_sysid = f.getValue('substation');
        }
    }

    // Aggregation logic
    var aggregation = new GlideRecord('x_1966159_utilit_0_aggregations');
    aggregation.addQuery('aggregation_type', 'power_outage');
    aggregation.addQuery('substation', substation_sysid);
    aggregation.addQuery('active', true);
    aggregation.query();

    var ag_sysid = '';

    if (aggregation.next()) {

        aggregationSysId = aggregation.getValue('sys_id');

    } else {

        // Record creation
        var aggregation = new GlideRecord('x_1966159_utilit_0_aggregations');
        aggregation.initialize();
        aggregation.setValue('aggregation_type', request_type);
        aggregation.setValue('aggregation_request_subtype', request_subtype);
        aggregation.setValue('substation', substation_sysid);

        aggregationSysId = aggregation.insert();
    }

    // Aggregation Member record creation
    var aggregationMember = new GlideRecord(
        'x_1966159_utilit_0_aggregation_members'
    );

    aggregationMember.initialize();
    aggregationMember.setValue('aggregation', aggregationSysId);
    aggregationMember.setValue('power_outage_request', requestsysId);

    var aggregationMembersysid = aggregationMember.insert();

    // Update Aggregation Total Requests
    if (aggregationMembersysid) {

        var updateAggregation = new GlideRecord(
            'x_1966159_utilit_0_aggregations'
        );

        updateAggregation.get(aggregationSysId);

        var totalRequests = parseInt(
            updateAggregation.getValue('total_requests'), 10
        );

        totalRequests = totalRequests + 1;

        updateAggregation.setValue('total_requests', totalRequests);
        updateAggregation.update();
    }
},


    type: 'AggregationManagementUtils'
}
;
